  // --- App (API verificate nella 0.3) ---
  function AppsAdapter(sdk) {
    return {
      list: function () {
        var apps = sdk.me.req('app-service').getData('getAppList', { sceneCode: 'launcher' }).result;
        if (!Array.isArray(apps)) throw new Error('getAppList non ha restituito un elenco');
        return apps.filter(function (a) { return a && a.appId && a.appName && CONFIG.HIDDEN_APP_IDS.indexOf(String(a.appId)) < 0; });
      },
      launch: function (app) {
        var options = { name: app.appName, appId: String(app.appId), url: app.url || '', storeType: app.storeType };
        if (sdk.apc.CMDMETHOD) options.startMethod = sdk.apc.CMDMETHOD.LAUNCHER_SMALLWINDOW;
        sdk.apc.start(options);
      },
      // Percorso icona nella forma originale (es. 'var/local/storeAppIcon/ID'): mai convertito.
      image: function (app) { var image = app.img; return typeof image === 'string' ? image : (image && (image.url || image.src)) || ''; }
    };
  }
  // --- Ingressi (API verificate nella 0.3; si rileva hasSignal, non il cavo) ---
  function InputsAdapter(sdk) {
    return {
      list: function () {
        var inputs = sdk.me.req('all-inputs').getData('getAllInputsData').result;
        if (!Array.isArray(inputs)) return [];
        return inputs.filter(function (i) { return i && i.sourceType === 'physicalInput' && (i.sourceId === 'TV' || /^HDMI/i.test(i.sourceId)); }).slice(0, 6);
      },
      change: function (input) { sdk.me.req('all-inputs').invoke('changeSourceTo', input.sourceId, 'launcher'); }
    };
  }
