        notConnected: function (row) {
          var self = this;
          this.openDialog({ title: row.label, message: 'Voce non ancora collegata alla TV: nessuna modifica applicata.', def: 0, buttons: [
            { label: 'Apri menu originale', run: function () { self.openOriginalSettings(); } },
            { label: 'Chiudi', run: function () {} }] });
        },
        setRow: function (lv, row, value) {
          if (lv.id === 'personalize') return this.setPref(row.id, value);
          if (row.id === 'appFav') return this.setFavorite(this.appById[lv.appId], value);
          if (row.id === 'appHidden') { this.toggleHidden(this.appById[lv.appId]); return this.persist(); }
          if (row.disabled) return this.showToast('Opzione non disponibile per la sorgente attuale.');
          if (!Settings.write(row.id, value)) return this.notConnected(row);
          var self = this, expected = value, id = row.id;
          this._saveTokens = this._saveTokens || {};
          var token = (this._saveTokens[id] || 0) + 1; this._saveTokens[id] = token;
          function verifySave(attempt) {
            if (self._isDestroyed || self._saveTokens[id] !== token) return;
            var actual = Settings.read(id);
            if (String(actual) === String(expected)) {
              var values = assign({}, self.svals); values[id] = actual; self.svals = values;
              return;
            }
            if (attempt < 4) return setTimeout(function () { verifySave(attempt + 1); }, 500);
            self.showToast('La TV non ha confermato il valore selezionato.');
          }
          setTimeout(function () { verifySave(0); }, 150);
        },
        selectable: function (r) { return r && r.type !== 'info'; },
        firstSel: function (rows) { for (var i = 0; i < rows.length; i++) if (this.selectable(rows[i])) return i; return 0; },
        nextSel: function (rows, i, d) { var j = i + d; while (j >= 0 && j < rows.length) { if (this.selectable(rows[j])) return j; j += d; } return i; },
        // Reti Wi‑Fi e Bluetooth a schermo intero dentro Impostazioni: stessi dati e stessa tastiera del pannello rapido.
