          if (row.type === 'appdetail') return this.pushLevel(st, { kind: 'app', appId: String(row.app.appId) });
          if (row.type === 'diag') return this.pushLevel(st, { kind: 'diag' });
          if (row.type === 'choice') { var ci = 0; (row.options || []).forEach(function (o, i) { if (o.value === row.value) ci = i; }); st.push({ kind: 'choice', row: row.id, i: ci }); return; }
          if (row.type === 'native') return this.openOriginalSettings();
